#![allow(dead_code)]

// Transport-facing DTO. This is the shape the HTTP body decodes into.
#[derive(Debug, Clone)]
struct CreateInvoiceRequest {
    customer_id: String,
    line_totals: Vec<u64>,
}

// Application command. The service knows only this, never the HTTP request.
#[derive(Debug, Clone)]
struct CreateInvoiceCommand {
    tenant: String,
    customer_id: String,
    line_totals: Vec<u64>,
}

#[derive(Debug, Clone)]
struct Invoice {
    id: String,
    tenant: String,
    total_cents: u64,
}

#[derive(Debug)]
enum DomainError {
    EmptyInvoice,
    Unauthorized,
}

// Transport-facing error. Lives at the edge, never inside the service.
#[derive(Debug)]
enum ApiError {
    BadRequest(&'static str),
    Forbidden,
}

struct InvoiceService;

impl InvoiceService {
    // The service boundary works only from a command and returns a domain type.
    fn create_invoice(&self, cmd: CreateInvoiceCommand) -> Result<Invoice, DomainError> {
        if cmd.line_totals.is_empty() {
            return Err(DomainError::EmptyInvoice);
        }

        let total_cents: u64 = cmd.line_totals.iter().copied().sum();

        Ok(Invoice {
            id: format!("inv-{}", cmd.customer_id),
            tenant: cmd.tenant,
            total_cents,
        })
    }
}

// Typed application state: the shared service plus a name. No HTTP types here.
struct ApiState {
    invoices: InvoiceService,
    service_name: String,
}

// One caller context object, derived once by an auth extractor at the edge.
#[derive(Debug)]
struct AuthenticatedUser {
    tenant: String,
    can_create: bool,
}

#[derive(Debug)]
struct CreatedInvoiceResponse {
    status: u16,
    request_id: String,
    invoice_id: String,
    tenant: String,
    total_cents: u64,
}

// The handler is the only place that knows about both HTTP and the command:
// authorize, map DTO into command, call the service once, translate the error.
fn create_invoice_handler(
    state: &ApiState,
    actor: AuthenticatedUser,
    request_id: &str,
    body: CreateInvoiceRequest,
) -> Result<CreatedInvoiceResponse, ApiError> {
    // Edge authorization happens before the service is touched.
    if !actor.can_create {
        return Err(ApiError::Forbidden);
    }

    // Build exactly one command. The tenant comes from the caller context,
    // not from the request body, so a client cannot spoof another tenant.
    let cmd = CreateInvoiceCommand {
        tenant: actor.tenant,
        customer_id: body.customer_id,
        line_totals: body.line_totals,
    };

    let created = state
        .invoices
        .create_invoice(cmd)
        .map_err(|err| match err {
            DomainError::EmptyInvoice => {
                ApiError::BadRequest("invoice must contain at least one line")
            }
            DomainError::Unauthorized => ApiError::Forbidden,
        })?;

    Ok(CreatedInvoiceResponse {
        status: 201,
        request_id: request_id.to_string(),
        invoice_id: created.id,
        tenant: created.tenant,
        total_cents: created.total_cents,
    })
}

fn main() {
    let state = ApiState {
        invoices: InvoiceService,
        service_name: String::from("billing-api"),
    };
    let actor = AuthenticatedUser {
        tenant: String::from("acme"),
        can_create: true,
    };
    // customer_id "7" yields invoice id "inv-7" to match the expected output.
    let request = CreateInvoiceRequest {
        customer_id: String::from("7"),
        line_totals: vec![1_200_u64, 3_000],
    };

    let created = create_invoice_handler(&state, actor, "req-7", request).unwrap();

    println!("status = {}", created.status);
    println!("invoice = {}", created.invoice_id);
    println!("tenant = {}", created.tenant);
}
